/** Resolve `auth.users`, `storage.objects`, `public.contacts` or a bare MySQL name. */
export function resolveTableName(name: string): TableName | undefined {
  if (name in PG_TABLE_ALIASES) return PG_TABLE_ALIASES[name as keyof typeof PG_TABLE_ALIASES]
  if (name in SCHEMA.tables) return name as TableName
  return undefined
}

export function tableSchema(name: TableName): TableSchema {
  return SCHEMA.tables[name] as unknown as TableSchema
}
